// Audio for course v2: every German sentence gets a pre-generated MP3 served by the web app at
// /audio/<voice>/<hash>.mp3 (frontend/public/audio, generated by v2/generate-audio.ts with Piper).
// The URL is derived from voice + spoken text, so re-imports reuse files and a changed sentence or
// voice gets a new URL (no stale service-worker cache). Missing files fall back to the device voice.
import { createHash } from "node:crypto";
import { existsSync,readFileSync } from "node:fs";
import { parseScript } from "./script.js";
import type { Entry,GlossaryMap } from "./tokens.js";

/**
 * Piper voice per speaker type (models from huggingface.co/rhasspy/piper-voices). Only Thorsten (CC0)
 * is clear enough among the free German voices (Whisper checks, 2026-10-22: Kerstin/Eva/Ramona and
 * the MLS speakers garble too many words), so both map to it for now. Content keeps "m"/"f" per
 * dialogue speaker: switching "f" to a premium female voice later only needs a new name here and a
 * generator run (new URLs, so no stale caches).
 */
export const VOICES = { m: "thorsten-high", f: "thorsten-high" } as const;
export type VoiceKey = keyof typeof VOICES;

/**
 * Voices for test recordings, where a man and a woman must sound different (Goethe listening parts).
 * Kerstin reads full sentences as clearly as Thorsten (Whisper, 2026-10-22: 0.87 vs 0.89 word recall
 * on exam-style lines) but not single words, so lessons keep Thorsten.
 */
export const EXAM_VOICES = { m: "thorsten-high", f: "kerstin-low" } as const;

/** What the voice should say for a display string: no slashes, ellipses, arrows or hints in brackets. */
export function spokenText(display: string): string {
  return display
    .normalize("NFC")
    .replace(/[↘↗→←↑↓]/g, "")
    .replace(/\([^)]*\)/g, "")
    .replace(/…|\.\.\./g, "")
    .replace(/\s+[—–]\s+/g, ", ")
    .replace(/\s*\/\s*/g, ", ")
    .replace(/_{3,}/g, "")
    .replace(/\s+([,.!?;:])/g, "$1")
    .replace(/([,;:])(?:\s*[,;:])+/g, "$1")
    .replace(/([.!?])\s*[,;:]/g, "$1")
    .replace(/^[,;:\s]+|[,;:\s]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/** Dictionary form of a vocabulary entry as spoken: "der Name, -n" → "der Name", "auf|stehen" → "aufstehen". */
export function spokenHeadword(display: string): string {
  return spokenText(display.replace(/,\s*(?:¨?-[\p{L}]*|¨|-)\s*$/u, "").replace(/\|/g, ""));
}

/** One voice reading `text`, or a conversation: `parts` joined into one clip with a short pause per turn. */
export type AudioClip = { url: string; voice: string; text: string } | { url: string; parts: { voice: string; text: string }[] };

const hash16 = (value: string) => createHash("sha1").update(value).digest("hex").slice(0, 16);
const clipUrl = (voiceName: string, spoken: string) => `/audio/${voiceName}/${hash16(`${voiceName}|${spoken}`)}.mp3`;
const speakable = (text: string) => /[\p{L}\d]/u.test(text);

export function audioUrl(spoken: string, voice: VoiceKey): string {
  return clipUrl(VOICES[voice], spoken);
}

const skipFile = new URL("./audio-skip.json", import.meta.url);
/** Word clips that no version passed the listen-check (fix_word_audio.py): better no speaker than a wrong word. */
const unclear = new Set<string>(existsSync(skipFile) ? (JSON.parse(readFileSync(skipFile, "utf8")) as string[]) : []);

/** `url` unless the listen-check found that word clip unclear. */
export const usableClip = (url: string | undefined) => (url && !unclear.has(url) ? url : undefined);

/**
 * The glossary with each tappable word's recording as third element ([English, dictionary form or "", URL]),
 * so tap-a-word plays the lesson's voice. No recording for an abbreviation ("EN", "Nr."), a source glitch
 * that glued two words together ("maisonIhr") or a clip the listen-check found unclear: the popover then
 * shows no speaker.
 */
export function withWordAudio(glossary: GlossaryMap, say: (display: string) => string | undefined): GlossaryMap {
  return Object.fromEntries(Object.entries(glossary).map(([form, [english, lemma]]): [string, Entry] => {
    const url = /\p{Ll}\p{Lu}/u.test(form) || /abbreviation/i.test(english) ? undefined : usableClip(say(form));
    return [form, url ? [english, lemma ?? "", url] : lemma === undefined ? [english] : [english, lemma]];
  }));
}

/** Collects every clip a build needs, so the generator can create the missing ones. */
export class AudioCollector {
  private clips = new Map<string, AudioClip>();

  /** URL for `display` spoken by `voice`; undefined when nothing speakable is left. */
  say(display: string | undefined, voice: VoiceKey = "m", spoken?: string): string | undefined {
    if (!display) return undefined;
    const text = spoken ? spokenText(spoken) : spokenText(display);
    if (!speakable(text)) return undefined;
    const url = audioUrl(text, voice);
    this.clips.set(url, { url, voice: VOICES[voice], text });
    return url;
  }

  /** URL of a test recording (see script.ts): one exam voice, or a whole conversation as one clip. */
  script(script: string | undefined): string | undefined {
    const turns = parseScript(script ?? "").map((turn) => ({ voice: EXAM_VOICES[turn.speaker], text: spokenText(turn.text) }))
      .filter((turn) => speakable(turn.text));
    const [first] = turns;
    if (!first) return undefined;
    const url = turns.length === 1 ? clipUrl(first.voice, first.text) : `/audio/dialogue/${hash16(JSON.stringify(turns))}.mp3`;
    this.clips.set(url, turns.length === 1 ? { url, ...first } : { url, parts: turns });
    return url;
  }

  list(): AudioClip[] {
    return [...this.clips.values()];
  }
}
